    CreateReservationRequest body;
    try {
        body = ctx.bodyAsClass(CreateReservationRequest.class);
    } catch (Exception unreadableBody) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
    }
    if (body == null
            || body.roomNumber() == null
            || isBlank(body.guestName())
            || isBlank(body.guestEmail())
            || body.checkIn() == null
            || body.checkOut() == null
            || body.guests() == null
            || body.ratePlan() == null) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
    }

    Identification identification = createIdentification(body);
    Guest guest = new Guest(body.guestName(), body.guestEmail(), identification);
    return new NewReservation(
            body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
}

private static Identification createIdentification(CreateReservationRequest body) {
    boolean hasCpf = !isBlank(body.guestCpf());
    boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
    boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());

    int count = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);

    if (count == 0 || count > 1) {
        throw new HotelException(
                ErrorCode.INVALID_REQUEST,
                "provide either guestCpf, or companyCnpj and companyName, or guestPassport and guestCountry");
    }

    if (hasCpf) {
        return new Identification.CpfIdentification(body.guestCpf());
    } else if (hasCompany) {
        return new Identification.CompanyIdentification(body.companyCnpj(), body.companyName());
    } else {
        return new Identification.PassportIdentification(body.guestPassport(), body.guestCountry());
    }
}

